import { Routes } from '@angular/router';
import { NoteList } from './note-list/note-list';
import { NoteDetail } from './note-detail/note-detail';
import { NotFound } from './not-found/not-found';
import { NoteForm } from './note-form/note-form';

export const routes: Routes = [
  { path: '**', component: NotFound },
  { path: '', redirectTo: 'notes' },
  { path: 'notes', component: NoteList },
  { path: 'notes/new', component: NoteForm },
  { path: 'notes/:id', component: NoteDetail },
];

import { Component, inject } from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';

@Component({
  selector: 'app-note-form',
  template: `
    <form [formGroup]="form" (ngSubmit)="save()" class="space-y-3">
      <label class="block">Title <input class="border" formControlName="tittle"></label>
      <label class="block">Body <textarea class="border" formControlName="body"></textarea></label>
      <button class="rounded bg-slate-900 px-3 py-1 text-white" [disabled]="form.invalid">Save</button>
    </form>
  `,
})
export class NoteForm {
  private fb = inject(FormBuilder);
  form = this.fb.nonNullable.group({
    title: ['', Validators.required, Validators.minLength(3)],
    body: [''],
  });

  save() {
    console.log(this.form.getRawValue());
  }
}
